    76      /* Send or buffer a WebSocket frame, compressed or not. Returns BACKPRESSURE on increased user space backpressure,
    77       * DROPPED on dropped message (due to backpressure) or SUCCCESS if you are free to send even more now. */
    78      SendStatus send(std::string_view message, OpCode opCode = OpCode::BINARY, bool compress = false) {
    79          WebSocketContextData<SSL, USERDATA> *webSocketContextData = (WebSocketContextData<SSL, USERDATA> *) us_socket_context_ext(SSL,
    80              (us_socket_context_t *) us_socket_context(SSL, (us_socket_t *) this)
    81          );
    82
    83          /* Skip sending and report success if we are over the limit of maxBackpressure */
    84          if (webSocketContextData->maxBackpressure && webSocketContextData->maxBackpressure < getBufferedAmount()) {
    85              /* Also defer a close if we should */
    86              if (webSocketContextData->closeOnBackpressureLimit) {
    87                  us_socket_shutdown_read(SSL, (us_socket_t *) this);
    88              }
    89              return DROPPED;
    90          }
    91
    92          /* If we are subscribers and have messages to drain we need to drain them here to stay synced */
    93          WebSocketData *webSocketData = (WebSocketData *) Super::getAsyncSocketData();
    94          if (webSocketData->subscriber) {
    95              /* This will call back into us, send. */
    96              webSocketContextData->topicTree.drain(webSocketData->subscriber);
    97          }
    98
    99          /* Transform the message to compressed domain if requested */
   100          if (compress) {
   101              WebSocketData *webSocketData = (WebSocketData *) Super::getAsyncSocketData();
   102
   103              /* Check and correct the compress hint. It is never valid to compress 0 bytes */
   104              if (message.length() && opCode < 3 && webSocketData->compressionStatus == WebSocketData::ENABLED) {
   105                  LoopData *loopData = Super::getLoopData();
   106                  /* Compress using either shared or dedicated deflationStream */
   107                  if (webSocketData->deflationStream) {
   108                      message = webSocketData->deflationStream->deflate(loopData->zlibContext, message, false);
   109                  } else {
   110                      message = loopData->deflationStream->deflate(loopData->zlibContext, message, true);
   111                  }
   112              } else {
   113                  compress = false;
   114              }
   115          }
   116
   117          /* Get size, allocate size, write if needed */
   118          size_t messageFrameSize = protocol::messageFrameSize(message.length());
   119          auto [sendBuffer, sendBufferAttribute] = Super::getSendBuffer(messageFrameSize);
   120          protocol::formatMessage<isServer>(sendBuffer, message.data(), message.length(), opCode, message.length(), compress);
   121
   122          /* Depending on size of message we have different paths */
   123          if (sendBufferAttribute == SendBufferAttribute::NEEDS_DRAIN) {
   124              /* This is a drain */
   125              auto[written, failed] = Super::write(nullptr, 0);
   126              if (failed) {
   127                  /* Return false for failure, skipping to reset the timeout below */
   128                  return BACKPRESSURE;
   129              }
   130          } else if (sendBufferAttribute == SendBufferAttribute::NEEDS_UNCORK) {
   131              /* Uncork if we came here uncorked */
   132              auto [written, failed] = Super::uncork();
   133              if (failed) {
   134                  return BACKPRESSURE;
   135              }
   136          }
   137
   138          /* Every successful send resets the timeout */
   139          if (webSocketContextData->resetIdleTimeoutOnSend) {
   140              Super::timeout(webSocketContextData->idleTimeoutComponents.first);
   141              WebSocketData *webSocketData = (WebSocketData *) Super::getAsyncSocketData();
   142              webSocketData->hasTimedOut = false;
   143          }
   144
   145          /* Return success */
   146          return SUCCESS;
   147      }
