   149      /* Send websocket close frame, emit close event, send FIN if successful.
   150       * Will not append a close reason if code is 0 or 1005. */
   151      void end(int code = 0, std::string_view message = {}) {
   152          /* Check if we already called this one */
   153          WebSocketData *webSocketData = (WebSocketData *) us_socket_ext(SSL, (us_socket_t *) this);
   154          if (webSocketData->isShuttingDown) {
   155              return;
   156          }
   157
   158          /* We postpone any FIN sending to either drainage or uncorking */
   159          webSocketData->isShuttingDown = true;
   160
   161          /* Format and send the close frame */
   162          static const int MAX_CLOSE_PAYLOAD = 123;
   163          size_t length = std::min<size_t>(MAX_CLOSE_PAYLOAD, message.length());
   164          char closePayload[MAX_CLOSE_PAYLOAD + 2];
   165          size_t closePayloadLength = protocol::formatClosePayload(closePayload, (uint16_t) code, message.data(), length);
   166          bool ok = send(std::string_view(closePayload, closePayloadLength), OpCode::CLOSE);
   167
   168          /* FIN if we are ok and not corked */
   169          if (!this->isCorked()) {
   170              if (ok) {
   171                  /* If we are not corked, and we just sent off everything, we need to FIN right here.
   172                   * In all other cases, we need to fin either if uncork was successful, or when drainage is complete. */
   173                  this->shutdown();
   174              }
   175          }
   176
   177          WebSocketContextData<SSL, USERDATA> *webSocketContextData = (WebSocketContextData<SSL, USERDATA> *) us_socket_context_ext(SSL,
   178              (us_socket_context_t *) us_socket_context(SSL, (us_socket_t *) this)
   179          );
   180
   181          /* Set shorter timeout (use ping-timeout) to avoid long hanging sockets after end() on broken connections */
   182          Super::timeout(webSocketContextData->idleTimeoutComponents.second);
   183
   184          /* Emit close event */
   185          if (webSocketContextData->closeHandler) {
   186              webSocketContextData->closeHandler(this, code, message);
   187          }
   188
   189          /* Make sure to unsubscribe from any pub/sub node at exit */
   190          webSocketContextData->topicTree.freeSubscriber(webSocketData->subscriber);
   191          webSocketData->subscriber = nullptr;
   192      }
