   194      /* Corks the response if possible. Leaves already corked socket be. */
   195      void cork(MoveOnlyFunction<void()> &&handler) {
   196          if (!Super::isCorked() && Super::canCork()) {
   197              Super::cork();
   198              handler();
   199
   200              /* There is no timeout when failing to uncork for WebSockets,
   201               * as that is handled by idleTimeout */
   202              auto [written, failed] = Super::uncork();
   203          } else {
   204              /* We are already corked, or can't cork so let's just call the handler */
   205              handler();
   206          }
   207      }
