   209      /* Subscribe to a topic according to MQTT rules and syntax. Returns success */
   210      bool subscribe(std::string_view topic, bool = false) {
   211          WebSocketContextData<SSL, USERDATA> *webSocketContextData = (WebSocketContextData<SSL, USERDATA> *) us_socket_context_ext(SSL,
   212              (us_socket_context_t *) us_socket_context(SSL, (us_socket_t *) this)
   213          );
   214
   215          /* Make us a subscriber if we aren't yet */
   216          WebSocketData *webSocketData = (WebSocketData *) us_socket_ext(SSL, (us_socket_t *) this);
   217          if (!webSocketData->subscriber) {
   218              webSocketData->subscriber = webSocketContextData->topicTree.createSubscriber();
   219              webSocketData->subscriber->user = this;
   220          }
   221
   222          /* Cannot return numSubscribers as this is only for this particular websocket context */
   223          webSocketContextData->topicTree.subscribe(webSocketData->subscriber, topic);
   224
   225          /* Subscribe always succeeds */
   226          return true;
   227      }
