   229      /* Unsubscribe from a topic, returns true if we were subscribed. */
   230      bool unsubscribe(std::string_view topic, bool = false) {
   231          WebSocketContextData<SSL, USERDATA> *webSocketContextData = (WebSocketContextData<SSL, USERDATA> *) us_socket_context_ext(SSL,
   232              (us_socket_context_t *) us_socket_context(SSL, (us_socket_t *) this)
   233          );
   234
   235          WebSocketData *webSocketData = (WebSocketData *) us_socket_ext(SSL, (us_socket_t *) this);
   236
   237          /* Cannot return numSubscribers as this is only for this particular websocket context */
   238          auto [ok, last] = webSocketContextData->topicTree.unsubscribe(webSocketData->subscriber, topic);
   239
   240          /* Free us as subscribers if we unsubscribed from our last topic */
   241          if (ok && last) {
   242              webSocketContextData->topicTree.freeSubscriber(webSocketData->subscriber);
   243              webSocketData->subscriber = nullptr;
   244          }
   245
   246          return ok;
   247      }
