    81      /* This is run once on start-up */
    82      void calculateIdleTimeoutCompnents(unsigned short idleTimeout) {
    83          unsigned short margin = 4;
    84          /* 4, 8 or 16 seconds margin based on idleTimeout */
    85          while ((int) idleTimeout - margin * 2 >= margin * 2 && margin < 16) {
    86              margin = (unsigned short) (margin << 1);
    87          }
    88          idleTimeoutComponents = {
    89              idleTimeout - (sendPingsAutomatically ? margin : 0), /* reduce normal idleTimeout if it is extended by ping-timeout */
    90              margin /* ping-timeout - also used for end() timeout */
    91          };
    92      }
